-- 0086_library_sections.sql (admin website builder, Task 9)
--
-- The admin-managed section library: one row per "Add section" design. `tree`
-- is the published NodeTemplate in slot form (images are `stock:photo:N` /
-- `stock:person:N` placeholders resolved for the inserting store's industry);
-- `draft_tree` holds unpublished admin edits (null = none).
--
-- The seed below is generated from the code designs (DESIGNS) by
-- `pnpm --filter @workspace/store-sections section:sql` and is insert-only
-- (ON CONFLICT (key) DO NOTHING): a re-run never overwrites admin edits.
-- A test checks this file contains the generator output verbatim.
--
-- Also creates the public `library-media` bucket for admin template/section
-- images. Same raster-only MIME list and 5 MB limit as `store-media` (0053,
-- packages/lib/src/media/media.lib.ts); no SVG, since a public bucket would
-- serve it. Writes are by the service role only (no storage policies).
--
-- Idempotent. library_sections: RLS enabled with no policies (server-side Drizzle only).

CREATE TABLE IF NOT EXISTS library_sections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key text NOT NULL UNIQUE CHECK (key ~ '^[a-z0-9-]+$'),
  category text NOT NULL,
  subcategory text NOT NULL DEFAULT '',
  name jsonb NOT NULL,
  description jsonb NOT NULL DEFAULT '{}',
  keywords text[] NOT NULL DEFAULT '{}',
  tree jsonb NOT NULL,             -- published NodeTemplate, slot form
  draft_tree jsonb,                -- null = no unpublished changes
  version integer NOT NULL DEFAULT 1,
  draft_version integer NOT NULL DEFAULT 1,
  thumbnail_url text,
  is_hidden boolean NOT NULL DEFAULT false,
  sort_order integer NOT NULL DEFAULT 0,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);

CREATE INDEX IF NOT EXISTS library_sections_listing_idx ON library_sections (category, sort_order) WHERE deleted_at IS NULL AND NOT is_hidden;

ALTER TABLE library_sections ENABLE ROW LEVEL SECURITY;

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'library-media', 'library-media', true, 5242880,
  ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/gif']
)
ON CONFLICT (id) DO NOTHING;

-- Seed: one row per design, in DESIGNS order (sort_order = index * 10).

